import re
import sys


def main():
    text = sys.stdin.read()
    paragraphs = []
    current_paragraph = []
    for line in text.split("\n"):
        line = line.strip()
        if not line:
            if current_paragraph:
                paragraphs.append("\n".join(current_paragraph))
                current_paragraph = []
        else:
            current_paragraph.append(line)
    if current_paragraph:
        paragraphs.append("\n".join(current_paragraph))

    sentences = []
    sentence_end = False
    for paragraph in paragraphs:
        for line in paragraph.split("."):
            line = line.strip()
            if not line:
                continue
            terminator_found = False
            if line.endswith(("!", "?", "!?", "..")):
                terminator_found = True
                if line.lower() not in {"mr", "mrs", "dr", "st"}:
                    sentence_end = True
            if terminator_found or sentence_end:
                sentence_end = False
                if line:
                    sentences.append(line)
    sentences = [s for s in sentences if s.strip()]

    words = []
    for paragraph in paragraphs:
        for line in paragraph.split():
            line = line.strip()
            if not line:
                continue
            word = re.findall(r"[A-Za-z0-9\']+", line)[0]
            words.append(word)

    print("paragraphs", len(paragraphs))
    print("sentences", len(sentences))
    print("words", len(words))
    longest = max(words, key=lambda x: len(x), default="-")
    print("longest", longest)


if __name__ == "__main__":
    main()
